import{_ as e,a}from"./chunks/racquet_detail.5lhaXGbQ.js";import{_ as o,o as r,c as d,a0 as i}from"./chunks/framework.akKRIpjQ.js";const b=JSON.parse('{"title":"03 · Rackets (Profile)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/03-racquets.md","filePath":"guide/03-racquets.md"}'),n={name:"guide/03-racquets.md"};function s(l,t,h,c,u,g){return r(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="_03-·-rackets-profile" tabindex="-1">03 · Rackets (Profile) <a class="header-anchor" href="#_03-·-rackets-profile" aria-label="Permalink to &quot;03 · Rackets (Profile)&quot;">​</a></h1><blockquote><p>Feature 2 of 4. Record each racket you own — brand, model, headsize, length, weight, balance, tension target — all on-device.</p></blockquote><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><img src="'+e+'" alt="Racket list" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>A &quot;racket collection&quot; page on the <code>Rackets</code> tab. Each card shows the racket&#39;s photo (if set) and a one-line summary:</p><ul><li>Cover photo (optional)</li><li>Name</li><li>Brand · Model</li><li>Headsize</li><li>Last restring date</li></ul><p><code>+ Add racket</code> opens a form; the card&#39;s menu offers <code>Edit</code> / <code>Delete</code> / <code>Set reminder</code>.</p><h2 id="add-a-racket" tabindex="-1">Add a racket <a class="header-anchor" href="#add-a-racket" aria-label="Permalink to &quot;Add a racket&quot;">​</a></h2><ol><li><code>Rackets</code> tab → <code>+ Add racket</code></li><li>Fill the form (minimum 4 fields, others optional):</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td>Name</td><td>✅</td><td>e.g. &quot;Main Blade&quot; / &quot;Backup Pro Staff&quot;</td></tr><tr><td>Brand</td><td>✅</td><td>Dropdown; can be custom</td></tr><tr><td>Model</td><td>✅</td><td>Dropdown; can be custom</td></tr><tr><td>Headsize</td><td>✅</td><td>Number + unit (default in²)</td></tr><tr><td>Length</td><td>❌</td><td>Default 27&quot;</td></tr><tr><td>Strung weight</td><td>❌</td><td>g or oz</td></tr><tr><td>Balance</td><td>❌</td><td>mm or in</td></tr><tr><td>String tension main / cross</td><td>❌</td><td>main / cross; can fill later</td></tr><tr><td>Notes</td><td>❌</td><td>&quot;Birthday gift / bought in 2019&quot;, etc.</td></tr><tr><td>Cover photo</td><td>❌</td><td>Pick from gallery or take a photo</td></tr></tbody></table><ol start="3"><li><code>Save</code></li></ol><blockquote><p>Added rackets show on <code>Rackets</code> tab as cards.</p></blockquote><h2 id="detail-page" tabindex="-1">Detail page <a class="header-anchor" href="#detail-page" aria-label="Permalink to &quot;Detail page&quot;">​</a></h2><img src="'+a+'" alt="Racket detail page" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>Tap any racket card to open the detail page. Four tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>What you do here</th></tr></thead><tbody><tr><td><strong>Profile</strong></td><td>Specs (read-only display of the form you filled; tap <code>Edit</code> to change)</td></tr><tr><td><strong>Stringing log</strong></td><td>All restring records (see <a href="./04-stringing-log.html">04 · Stringing log</a>)</td></tr><tr><td><strong>Reminder</strong></td><td>Set or edit a restring reminder (see <a href="./04-stringing-log.html#reminders">04 · Stringing log</a>)</td></tr><tr><td><strong>Notes</strong></td><td>Free-text notes you&#39;ve added</td></tr></tbody></table><p>The detail page also has <code>Edit</code> (top-right) and <code>Delete</code> (overflow menu).</p><h2 id="specs-101" tabindex="-1">Specs 101 <a class="header-anchor" href="#specs-101" aria-label="Permalink to &quot;Specs 101&quot;">​</a></h2><h3 id="head-size" tabindex="-1">Head Size <a class="header-anchor" href="#head-size" aria-label="Permalink to &quot;Head Size&quot;">​</a></h3><p>V1.0&#39;s default unit is <strong>square inches</strong>. Quick reference:</p><table tabindex="0"><thead><tr><th>Headsize (in²)</th><th>Style</th></tr></thead><tbody><tr><td>95–98</td><td>Control (small head)</td></tr><tr><td>98–100</td><td>Neutral</td></tr><tr><td>100–104</td><td>Forgiving</td></tr><tr><td>104–115</td><td>Oversize / recreational</td></tr></tbody></table><blockquote><p><strong>Note</strong>: the 4-bucket table above is a <strong>playstyle reference</strong> only. For DT ⇄ RT calculation in <a href="./05-tension-conversion.html#head-size-buckets-used-by-dt--rt">05 · Tension Conversion</a> the App collapses any headsize into <strong>3 buckets</strong> that match the ERT300 reference machine&#39;s DT anchor table — <strong>MID 83–94 / MID+ 95–105 / OVER 106–115 sq.in.</strong> You only need to pick the right bucket when using the tension converter.</p></blockquote><h3 id="strung-weight" tabindex="-1">Strung Weight <a class="header-anchor" href="#strung-weight" aria-label="Permalink to &quot;Strung Weight&quot;">​</a></h3><p>Look up &quot;strung weight&quot; for the model online.</p><table tabindex="0"><thead><tr><th>Range (g)</th><th>Style</th></tr></thead><tbody><tr><td>&lt; 300</td><td>Very light (attacking)</td></tr><tr><td>300–320</td><td>Standard</td></tr><tr><td>320–340</td><td>Control</td></tr><tr><td>&gt; 340</td><td>Heavy / powerful</td></tr></tbody></table><h3 id="balance" tabindex="-1">Balance <a class="header-anchor" href="#balance" aria-label="Permalink to &quot;Balance&quot;">​</a></h3><ul><li>In mm (more precise) or in</li><li>Most rackets sit at 320–340 mm (even balance ~320 mm; head-light below; head-heavy above)</li></ul><h2 id="why-a-profile" tabindex="-1">Why a profile? <a class="header-anchor" href="#why-a-profile" aria-label="Permalink to &quot;Why a profile?&quot;">​</a></h2><ul><li><strong>Set up once</strong>: the next restring record pre-fills the racket&#39;s tension target, headsize, etc.</li><li><strong>Reminder context</strong>: a reminder knows which racket to refer to (&quot;Main Blade is due&quot;)</li><li><strong>Cover photo</strong>: makes the list scannable when you own 5+ rackets</li></ul><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><h3 id="i-have-10-rackets-—-too-many-cards-to-scroll" tabindex="-1">I have 10 rackets — too many cards to scroll? <a class="header-anchor" href="#i-have-10-rackets-—-too-many-cards-to-scroll" aria-label="Permalink to &quot;I have 10 rackets — too many cards to scroll?&quot;">​</a></h3><p>The <code>Rackets</code> tab list supports swiping between cards (phone) or scrolling (tablet). You can also pin up to 4 rackets to the top via long-press.</p><h3 id="cover-photo-is-required" tabindex="-1">Cover photo is required? <a class="header-anchor" href="#cover-photo-is-required" aria-label="Permalink to &quot;Cover photo is required?&quot;">​</a></h3><p>No, it&#39;s optional. Rackets without a cover photo render as a placeholder card with the brand initial.</p><h3 id="where-does-the-last-restring-date-come-from" tabindex="-1">Where does the &quot;last restring date&quot; come from? <a class="header-anchor" href="#where-does-the-last-restring-date-come-from" aria-label="Permalink to &quot;Where does the &quot;last restring date&quot; come from?&quot;">​</a></h3><p>It&#39;s the most-recent record on the racket&#39;s <a href="./04-stringing-log.html">Stringing log</a> tab.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next?&quot;">​</a></h2><p>A racket profile without any restring records is just a name. Record a restring → see <a href="./04-stringing-log.html">04 · Stringing log</a>.</p><p>Or skip that: jump straight to the calculator — see <a href="./05-tension-conversion.html">05 · Tension conversion</a> for converting DT ⇄ RT ⇄ lbs ⇄ kg, with a one-tap <strong>Use this tension → log stringing</strong> handoff back to chapter 04.</p>',39)])])}const f=o(n,[["render",s]]);export{b as __pageData,f as default};
